<?php
declare(strict_types=1);require_once __DIR__.'/../src/Services/PersonFiscalData.php';use MiniErp\Services\PersonFiscalData;
function personAssert(bool $ok,string $m):void{if(!$ok){fwrite(STDERR,"ASSERTION FAILED: $m\n");exit(1);}}
$base=['tipo_pessoa'=>['cliente','fornecedor','transportadora'],'state_registration_indicator'=>'1','inscricao_estadual'=>'123','codigo_ibge'=>'4106902','country_code'=>'1058','country_name'=>'Brasil'];$pf=(new PersonFiscalData($base+['person_type'=>'PF','cpf_cnpj'=>'123.456.789-01','rg'=>'RG1']))->toArray();personAssert($pf['cpf_cnpj']==='12345678901'&&$pf['role_customer']===1&&$pf['role_supplier']===1&&$pf['role_carrier']===1,'PF and roles');$pj=(new PersonFiscalData($base+['person_type'=>'PJ','cpf_cnpj'=>'12.ABC.345/01DE-35']))->toArray();personAssert($pj['cpf_cnpj']==='12ABC34501DE35','alphanumeric CNPJ');$foreign=(new PersonFiscalData(['person_type'=>'FOREIGN','foreign_id'=>'EXT-1','tipo_pessoa'=>['cliente'],'state_registration_indicator'=>'9','country_code'=>'2499','country_name'=>'EXTERIOR']))->toArray();personAssert($foreign['foreign_id']==='EXT-1'&&$foreign['cpf_cnpj']==='','foreign id separated');foreach(['3','x'] as $bad)try{new PersonFiscalData($base+['person_type'=>'PF','cpf_cnpj'=>$bad]);personAssert(false,'invalid CPF rejected');}catch(InvalidArgumentException){}echo "PersonFiscalData OK\n";
